class HeuristicGradientMomentum:
    """
    A "Heuristic Gradient Momentum" (HGM) optimalizáló Python implementációja.
    Ez az optimalizáló a Jade architektúra specifikus tulajdonságaira van szabva,
    különös tekintettel az SSM állapotmátrix (A) stabilitására.
    """

    def __init__(
        self,
        params: List[Dict],
        lr: float = 1e3,
        betas: Tuple[float, float] = (0.9, 0.99),
        eps: float = 1e8,
        heuristic_momentum_window: int = 10,
        state_matrix_spectral_radius_target: float = 0.99,
        state_matrix_regularization_strength: float = 0.01
    ):
        if not 0.0 <= lr:
            raise ValueError(f"Invalid learning rate: {lr}")
        if not 0.0 <= eps:
            raise ValueError(f"Invalid epsilon value: {eps}")
        if not (0.0 <= betas[0] < 1.0 and 0.0 <= betas[1] < 1.0):
            raise ValueError(f"Invalid beta parameters: {betas}")

        self.defaults = {
            "lr": lr,
            "betas": betas,
            "eps": eps,
            "heuristic_momentum_window": heuristic_momentum_window,
            "state_matrix_spectral_radius_target": state_matrix_spectral_radius_target,
            "state_matrix_regularization_strength": state_matrix_regularization_strength,
        }
        self.param_groups = params
        self.state = {}

        for group in self.param_groups:
            for p in group['params']:
                self.state[id(p)] = {}

    def zero_grad(self):
        """Minden paraméter gradiensét nullázza."""
        for group in self.param_groups:
            for p in group['params']:
                if hasattr(p, 'grad') and p.grad is not None:
                    p.grad = np.zeros_like(p.data)

    def step(self):
        """Egy optimalizációs lépést hajt végre."""
        for group in self.param_groups:
            for p in group['params']:
                if not hasattr(p, 'grad') or p.grad is None:
                    continue

                grad = p.grad
                if np.any(np.isinf(grad)) or np.any(np.isnan(grad)):
                    logging.warning("NaN or Inf gradient detected. Skipping update for this parameter.")
                    continue

                state = self.state[id(p)]

                 Állapot inicializálása
                if 'step' not in state:
                    state['step'] = 0
                    state['exp_avg'] = np.zeros_like(p.data)   m_t
                    state['exp_avg_sq'] = np.zeros_like(p.data)  v_t
                    k = group.get('heuristic_momentum_window', self.defaults['heuristic_momentum_window'])
                    state['grad_history'] = np.zeros((k, p.data.shape))

                exp_avg, exp_avg_sq = state['exp_avg'], state['exp_avg_sq']
                state['step'] += 1

                 Update parameters (simplified implementation)
                lr = group.get('lr', self.defaults['lr'])
                p.data = lr  grad

