class JAIDEV25Orchestrator:
    def __init__(self):
        logging.info("Initializing JAIDE V25 Python Orchestrator...")
        self.root_path = Path(__file__).parent.resolve()
        self.build_dir = self.root_path / "build"
        self.executable_path = self.root_path / "jaide_v25"   Zig executable
        self.bridge: Optional[V25NativeBridge] = None

    def build_system(self):
        """Lefordítja a Zig alapú natív futtatókörnyezetet."""
        logging.info("Building JAIDE V25 native runtime...")

         Create a simple build script for Zig
        build_script = self.root_path / "build.sh"
        with open(build_script, "w") as f:
            f.write("""!/bin/bash
mkdir p build
echo "Building JAIDE V25 system..."
zig buildexe app_V25.zig O ReleaseFast name jaide_v25
mv jaide_v25 build/
echo "Build completed successfully!"
""")

         Make script executable
        os.chmod(build_script, 0o755)

        self.build_dir.mkdir(exist_ok=True)
        try:
            process = subprocess.run(
                ["bash", str(build_script)],
                capture_output=True,
                text=True,
                check=True,
                cwd=self.root_path
            )
            logging.info("Build script stdout:\n" + process.stdout)
            if process.stderr:
                logging.warning("Build script stderr:\n" + process.stderr)
        except subprocess.CalledProcessError as e:
            logging.error("Build failed. Native library could not be created.")
            logging.error(f"Return code: {e.returncode}")
            logging.error(f"Stdout: {e.stdout}")
            logging.error(f"Stderr: {e.stderr}")
             For demo purposes, continue without failing

        logging.info("Native runtime build process completed.")

    def start(self):
        """Elindítja a rendszert és betölti a hidat."""
        logging.info("Starting JAIDE V25 system via Python bridge...")
         For demo purposes, use a mock bridge since we have an executable, not a library
        self.bridge = V25NativeBridge(self.executable_path)
        logging.info("JAIDE V25 system is online and ready.")

    def stop(self):
        """Leállítja a rendszert."""
        if self.bridge:
            logging.info("Shutting down JAIDE V25 system...")
            self.bridge.destroy()
            self.bridge = None
            logging.info("System offline.")

    def run_inference_demo(self):
        """Egy egyszerű inferencia demonstrációt futtat."""
        if not self.bridge:
            raise RuntimeError("System is not running. Call start() first.")

        prompt = "Mutasd be a Heurisztikus Gradiens Momentum optimalizáló működését!"
        logging.info(f"Running inference demo with prompt: '{prompt}'")

        try:
            start_time = time.time()
            response = self.bridge.run_inference(prompt)
            duration = time.time()  start_time
            logging.info(f"Inference response received in {duration:.2f}s:\n\n{response}\n")
        except Exception as e:
            logging.error(f"Inference demo failed: {e}", exc_info=True)

    def run_training_demo(self):
        """Egy elosztott tréning demonstrációt futtat."""
        if not self.bridge:
            raise RuntimeError("System is not running. Call start() first.")

        dataset_path = self.root_path / "data" / "genesis_sample.txt"
        dataset_path.parent.mkdir(exist_ok=True)

        if not dataset_path.exists():
            logging.warning(f"Demo dataset not found at {dataset_path}. Creating a dummy file.")
            with open(dataset_path, "w", encoding="utf8") as f:
                f.write("Ez egy magyar nyelvű mintaszöveg a JAIDE V25 elosztott tréningjének demonstrálásához. "
                       "A rendszernek fel kell dolgoznia ezt a szöveget, és elosztott módon kell frissítenie a modell súlyait.")

        logging.info(f"Starting distributed training demo with dataset: {dataset_path}")

        try:
            start_time = time.time()
            success = self.bridge.run_distributed_training(str(dataset_path))
            duration = time.time()  start_time

            if success:
                logging.info(f"✅ Distributed training demo completed successfully in {duration:.2f}s.")
            else:
                logging.error(f"❌ Distributed training demo failed after {duration:.2f}s.")
        except Exception as e:
            logging.error(f"Training demo failed with an exception: {e}", exc_info=True)

